const QUESTIONS=[];
const REVIEW_PACKET="";
function unlockReview(){if(!engine.state?.done)throw Error("Спочатку завершіть тест");const bytes=Uint8Array.from(atob(REVIEW_PACKET),(c,i)=>c.charCodeAt(0)^((i*31+173)&255));const rows=JSON.parse(new TextDecoder().decode(bytes));QUESTIONS.forEach(q=>{const row=rows.find(row=>row[0]===q.questionId);Object.assign(q,{correctAnswerId:row[1],explanation:row[2],sourceSection:row[3]});});}

const SETTINGS={endpoint:"https://techhub-quiz-api.bolotin-denis.workers.dev"},KEY='it-quiz-011-015-v2',AUTH_KEY='techhub-auth-v1';
const $=id=>document.getElementById(id),escapeHTML=s=>String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
const uid=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2)+'-'+Math.random().toString(36).slice(2);
const engine=new QuizEngine(QUESTIONS,{now:()=>performance.now(),wall:()=>Date.now()},uid);
let saved=null,server=null,storageOK=true,locked=false,sending=false,auth=null;
function notice(text){$('notice').textContent=text;}
function authHeaders(extra={}){return auth?.sessionToken?{...extra,Authorization:'Bearer '+auth.sessionToken}:extra;}
function saveAuth(value){auth=value;try{value?localStorage.setItem(AUTH_KEY,JSON.stringify(value)):localStorage.removeItem(AUTH_KEY);}catch{}window.dispatchEvent(new CustomEvent('techhub-auth-changed',{detail:value}));}
function requireCatalogAuth(){if(SETTINGS.endpoint)location.href='quizzes.html';}
async function authRequest(path,options={}){const response=await fetch(SETTINGS.endpoint+path,{...options,headers:authHeaders(options.headers||{})});if(response.status===401){saveAuth(null);requireCatalogAuth();}return response;}
async function initAuth(){if(!SETTINGS.endpoint)return;const start=$('start-button');start.disabled=true;try{const raw=localStorage.getItem(AUTH_KEY);if(raw)auth=JSON.parse(raw);}catch{}if(!auth?.sessionToken||!auth?.leaderboardName){requireCatalogAuth();return;}try{const response=await authRequest('/auth/me');if(!response.ok)return;const value=await response.json();auth={...auth,expiresAt:value.expiresAt,user:value.user};saveAuth(auth);start.disabled=false;}catch{notice('Не вдалося перевірити сесію. Перевірте підключення до мережі.');}}
try{const raw=localStorage.getItem(KEY);if(raw){const candidate=JSON.parse(raw);const probe=new QuizEngine(QUESTIONS,{now:()=>performance.now(),wall:()=>Date.now()},uid);configureQuestions(BANK,QUESTIONS,candidate.questionSet);probe.restore(candidate);saved=candidate;server=candidate.server||null;if(server?.managementToken)server=null;}}catch(e){storageOK=false;notice('Збереження недоступне або пошкоджене. Можна почати новий тест; результати можна завантажити у JSON.');}
function persist(){if(!engine.state)return;try{const snapshot=engine.snapshot();snapshot.server=server;localStorage.setItem(KEY,JSON.stringify(snapshot));}catch{storageOK=false;notice('Автозбереження недоступне. Не закривайте сторінку; завантажте результати у JSON.');}}
function format(ms){const n=Math.floor(ms/1000);return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');}
function show(id){for(const screen of document.querySelectorAll('.screen'))screen.hidden=screen.id!==id;if(typeof globalThis.scrollTo==='function')globalThis.scrollTo({top:0,left:0,behavior:'instant'});}
function announce(text){$('announce').textContent=text;}
function renderQuestion(){show('quiz');const s=engine.state,q=QUESTIONS[s.index];$('position').textContent='Питання '+(s.index+1)+' із '+QUESTIONS.length;$('topic').textContent=q.articleId+' / '+ARTICLES.find(a=>a.articleId===q.articleId).title;$('bar-fill').style.width=(s.index/QUESTIONS.length*100)+'%';$('legend').textContent=q.text;$('options').innerHTML=q.options.map((o,i)=>'<label class="option" for="option-'+i+'"><input type="radio" name="answer" id="option-'+i+'" value="'+o.answerId+'"'+(s.selected===o.answerId?' checked':'')+'><span class="letter">'+String.fromCharCode(65+i)+'</span><span>'+escapeHTML(o.text)+'</span></label>').join('');$('next').textContent=s.index===QUESTIONS.length-1?'Завершити':'Далі';$('next').disabled=!s.selected;$('question-time').textContent='Час питання: '+format(engine.questionTime());$('timer').textContent=format(engine.total());$('legend').focus();announce('Питання '+(s.index+1)+' із '+QUESTIONS.length);}
function renderResult(){unlockReview();show('result');$('result-title').focus();const score=engine.score();$('score').innerHTML=score+' <small>/ '+QUESTIONS.length+'</small>';$('result-time').textContent=format(engine.total());$('participant').textContent=engine.state.participantName;$('accuracy').textContent=Math.round(score/QUESTIONS.length*100)+'%';$('review').innerHTML=engine.state.records.map((r,i)=>{const q=QUESTIONS[i],correct=q.correctAnswerId===r.answerId,right=q.options.find(o=>o.answerId===q.correctAnswerId);return '<details class="review '+(correct?'good':'bad')+'"'+(!correct?' open':'')+'><summary>'+(correct?'✓':'✕')+' '+(i+1)+'. '+escapeHTML(q.text)+'</summary><div class="detail"><p>Ваша відповідь: '+escapeHTML(r.answerText)+'</p>'+(!correct?'<p>Правильна відповідь: '+escapeHTML(right.text)+'</p>':'')+'<p>'+escapeHTML(q.explanation)+'</p><div class="source">Стаття '+q.articleId+' · '+escapeHTML(q.sourceSection)+'<br>Час відповіді: '+format(r.questionTimeMs)+'</div></div></details>';}).join('');updateDelivery();submitAttempt();announce('Тест завершено. Правильних відповідей: '+score+' із '+QUESTIONS.length);}
function updateDelivery(){if(!SETTINGS.endpoint){$('delivery').textContent='Результати збережено локально. Сервер результатів не налаштовано.';$('leaderboard-controls').hidden=true;return;}if(server?.accepted){$('delivery').textContent='Результат збережено на сервері.';$('leaderboard-controls').hidden=false;$('leaderboard-visible').checked=!!server.visible;$('save-leaderboard').disabled=false;$('retry').hidden=true;}else{$('delivery').textContent=sending?'Зберігаємо результат…':'Результат ще не надіслано.';$('leaderboard-controls').hidden=true;$('retry').hidden=sending;}}
async function submitAttempt(){if(!SETTINGS.endpoint||sending||server?.accepted||!engine.state?.done)return;if(!auth?.sessionToken){notice('Увійдіть через Google, щоб зберегти результат.');updateDelivery();return;}sending=true;updateDelivery();try{const response=await authRequest('/attempts',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({snapshot:engine.snapshot()})});if(!response.ok)throw Error('HTTP '+response.status);const ack=await response.json();server={...ack,visible:!!ack.showInLeaderboard};persist();}catch{notice('Не вдалося зберегти результат на сервері. Спробуйте ще раз.');}finally{sending=false;updateDelivery();}}
async function saveLeaderboard(){if(!server?.accepted||sending||!auth?.sessionToken)return;sending=true;$('save-leaderboard').disabled=true;try{const visible=$('leaderboard-visible').checked,response=await authRequest('/attempts/'+encodeURIComponent(server.attemptId)+'/leaderboard',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({visible})});if(!response.ok)throw Error('HTTP '+response.status);server.visible=(await response.json()).visible;persist();notice(server.visible?'Результат додано до рейтингу.':'Результат приховано з рейтингу.');}catch{$('leaderboard-visible').checked=!!server.visible;notice('Не вдалося змінити видимість у рейтингу.');}finally{sending=false;$('save-leaderboard').disabled=false;}}
$('start-form').addEventListener('submit',event=>{event.preventDefault();if(sending)return;if(SETTINGS.endpoint&&(!auth?.sessionToken||!auth?.leaderboardName)){requireCatalogAuth();return;}const field=$('name'),name=SETTINGS.endpoint?auth.leaderboardName:field.value.trim();if(!name){field.reportValidity();return;}QUESTIONS.forEach(q=>{delete q.correctAnswerId;delete q.explanation;delete q.sourceSection;});configureQuestions(BANK,QUESTIONS);engine.start(name);saved=null;server=null;persist();renderQuestion();});
$('options').addEventListener('change',event=>{if(event.target.name!=='answer'||locked)return;engine.select(event.target.value);$('next').disabled=false;persist();});
$('next').addEventListener('click',()=>{if(locked||!engine.state?.selected||engine.state.done)return;locked=true;$('next').disabled=true;const questionId=QUESTIONS[engine.state.index].questionId;const record=engine.commit(questionId);if(!record){locked=false;return;}persist();if(engine.state.done)renderResult();else renderQuestion();setTimeout(()=>locked=false,300);});
if(saved){$('resume-box').hidden=false;$('resume-description').textContent=saved.state.done?'Є завершений тест учасника «'+saved.state.participantName+'».': 'Є проходження учасника «'+saved.state.participantName+'»: '+saved.state.index+' із 20 відповідей. Час перерви входить у загальний час і час поточного питання.';$('resume').textContent=saved.state.done?'Показати результат':'Продовжити';}
$('resume').addEventListener('click',()=>{if(SETTINGS.endpoint&&(!auth?.sessionToken||!auth?.leaderboardName)){requireCatalogAuth();return;}try{configureQuestions(BANK,QUESTIONS,saved.questionSet);engine.restore(saved);persist();if(engine.state.done)renderResult();else renderQuestion();}catch{notice('Не вдалося відновити тест. Почніть нове проходження.');}});
$('new-test').addEventListener('click',()=>{if(sending)return;show('start');$('resume-box').hidden=true;if($('name')){$('name').value=engine.state.participantName;$('name').focus();}});
$('download').addEventListener('click',()=>{const snapshot=engine.snapshot();if(!snapshot)return;const data={...snapshot,score:engine.score(),pending:engine.state.records.filter(r=>r.delivery==='pending')};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='quiz-011-015-'+engine.state.attemptId+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
$('retry').addEventListener('click',submitAttempt);$('save-leaderboard').addEventListener('click',saveLeaderboard);addEventListener('online',submitAttempt);addEventListener('pagehide',persist);document.addEventListener('visibilitychange',persist);
initAuth();
setInterval(()=>{if(!engine.state||engine.state.done)return;$('timer').textContent=format(engine.total());$('question-time').textContent='Час питання: '+format(engine.questionTime());persist();},1000);
try{$('theme').checked=localStorage.getItem('article-theme')==='light'}catch{}$('theme').addEventListener('change',()=>{try{localStorage.setItem('article-theme',$('theme').checked?'light':'dark')}catch{}});

$("startup-warning").hidden=true;